begin;
select '1..3' as tap;
create function pg_temp.require(ok boolean) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Task assertion failed';end if;end$$;
create function pg_temp.rejects(command text,code text) returns void language plpgsql as $$begin begin execute command;exception when others then if sqlstate=code then return;end if;raise;end;raise exception 'Expected task rejection %',code;end$$;
create function pg_temp.data()returns jsonb language sql as $$select '{"title":"Fictional task","summary":"Safe task summary","body":"Private notes","classification":"restricted","leadUnitId":"44444444-4444-4444-8444-444444444441","parentId":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa9","dueOn":"2027-04-10","dueAt":null,"assigneeId":"33333333-3333-4333-8333-333333333331","assignedUnitId":"44444444-4444-4444-8444-444444444441","collaborators":[],"checklist":[{"id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","text":"Confirm checklist","done":false}],"taskType":"ordinary","reason":"Fictional reason"}'::jsonb$$;
create function pg_temp.v()returns integer language sql as $$select(public.read_task(current_setting('p10.id')::uuid)->>'version')::integer$$;
grant execute on function pg_temp.require(boolean),pg_temp.rejects(text,text),pg_temp.data(),pg_temp.v() to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333331',true);
select set_config('p10.id',public.create_task('22222222-2222-4222-8222-222222222221',pg_temp.data(),'10000000-0000-4000-8000-000000000001')->>'workItemId',true);
select pg_temp.require(public.create_task('22222222-2222-4222-8222-222222222221',pg_temp.data(),'10000000-0000-4000-8000-000000000001')->>'workItemId'=current_setting('p10.id'));
select pg_temp.rejects($q$select public.create_task('22222222-2222-4222-8222-222222222221',pg_temp.data()||'{"title":"Changed"}','10000000-0000-4000-8000-000000000001')$q$,'22023');
select pg_temp.rejects($q$select public.update_task(current_setting('p10.id')::uuid,pg_temp.data()||'{"assigneeId":"33333333-3333-4333-8333-333333333332"}',1,gen_random_uuid())$q$,'42501');
select pg_temp.rejects($q$update public.tasks set assignee_id='33333333-3333-4333-8333-333333333332' where work_item_id=current_setting('p10.id')::uuid$q$,'42501');
select pg_temp.rejects($q$update public.work_items set owner_member_id='33333333-3333-4333-8333-333333333332' where id=current_setting('p10.id')::uuid$q$,'42501');
select pg_temp.rejects($q$select public.update_task(current_setting('p10.id')::uuid,pg_temp.data()||'{"ownerId":"33333333-3333-4333-8333-333333333332"}',1,gen_random_uuid())$q$,'22023');
select pg_temp.rejects($q$select public.create_work_item('22222222-2222-4222-8222-222222222221','task','Bypass','','','restricted')$q$,'55000');
select pg_temp.rejects($q$select public.update_task(current_setting('p10.id')::uuid,pg_temp.data(),0,gen_random_uuid())$q$,'40001');
select 'ok 1 - P10_A1: duplicate retry returns one task, payload conflict/stale edit and unauthorized assignment/direct generic bypass denied' as tap;
select pg_temp.rejects($q$select public.assign_task(current_setting('p10.id')::uuid,'{"assigneeId":"33333333-3333-4333-8333-333333333332","assignedUnitId":"44444444-4444-4444-8444-444444444442","collaborators":[],"reason":"Imposed"}',pg_temp.v(),gen_random_uuid())$q$,'42501');
select public.grant_work_access(current_setting('p10.id')::uuid,'33333333-3333-4333-8333-333333333332',null,null,'edit',statement_timestamp()+interval'1 day',pg_temp.v(),gen_random_uuid());
reset role;
insert into public.role_assignments(organization_id,term_id,term_membership_id,role_id,scope_type,unit_id,effective_from,effective_to,granted_by)
values('11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222221','66666666-6666-4666-8666-666666666662','55555555-5555-4555-8555-555555555559','unit','44444444-4444-4444-8444-444444444442',statement_timestamp()-interval'1 day',statement_timestamp()+interval'1 day','66666666-6666-4666-8666-666666666661');
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333332',true);
select public.assign_task(current_setting('p10.id')::uuid,'{"assigneeId":"33333333-3333-4333-8333-333333333332","assignedUnitId":"44444444-4444-4444-8444-444444444442","collaborators":[],"reason":"Receiving head explicitly accepts"}',pg_temp.v(),gen_random_uuid());
select pg_temp.require(public.read_task(current_setting('p10.id')::uuid)->>'ownerId'='33333333-3333-4333-8333-333333333332');
select pg_temp.require(public.read_task(current_setting('p10.id')::uuid)->'parentId'='null'::jsonb);
select pg_temp.require(not public.can_access_work('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa9','summary'));
select pg_temp.require((public.read_tasks('22222222-2222-4222-8222-222222222221','watching')->>'total')::integer=1);
select 'ok 2 - P10_A2: sender cannot impose cross-unit work; current receiving head with exact task edit scope explicitly accepts' as tap;
reset role;
update public.role_assignments set status='revoked' where term_membership_id='66666666-6666-4666-8666-666666666662' and role_id='55555555-5555-4555-8555-555555555559';
select pg_temp.require((select created_by='33333333-3333-4333-8333-333333333331' and owner_member_id='33333333-3333-4333-8333-333333333332' from public.work_items where id=current_setting('p10.id')::uuid));
select pg_temp.rejects($q$update public.tasks set assignee_id='33333333-3333-4333-8333-333333333331' where work_item_id=current_setting('p10.id')::uuid;set constraints task_assignee_spine immediate$q$,'23514');
insert into public.role_assignments(organization_id,term_id,term_membership_id,role_id,scope_type,unit_id,effective_from,effective_to,granted_by)
values('11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222221','66666666-6666-4666-8666-666666666661','55555555-5555-4555-8555-555555555559','unit','44444444-4444-4444-8444-444444444441',statement_timestamp()-interval'1 day',statement_timestamp()+interval'1 day','66666666-6666-4666-8666-666666666662');
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333331',true);
select public.update_task(current_setting('p10.id')::uuid,pg_temp.data()||jsonb_build_object('assigneeId','33333333-3333-4333-8333-333333333332','assignedUnitId','44444444-4444-4444-8444-444444444442','dueOn',((statement_timestamp() at time zone 'Asia/Manila')::date)::text),pg_temp.v(),gen_random_uuid());
select pg_temp.require(public.read_task(current_setting('p10.id')::uuid)->>'overdue'='false');
select public.update_task(current_setting('p10.id')::uuid,pg_temp.data()||jsonb_build_object('assigneeId','33333333-3333-4333-8333-333333333332','assignedUnitId','44444444-4444-4444-8444-444444444442','dueOn',((statement_timestamp() at time zone 'Asia/Manila')::date-1)::text),pg_temp.v(),gen_random_uuid());
select pg_temp.require(public.read_task(current_setting('p10.id')::uuid)->>'overdue'='true');
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333332',true);
select pg_temp.rejects($q$select public.update_task(current_setting('p10.id')::uuid,pg_temp.data()||'{"assigneeId":"33333333-3333-4333-8333-333333333332","assignedUnitId":"44444444-4444-4444-8444-444444444442","dueOn":"2027-04-12"}',pg_temp.v(),gen_random_uuid())$q$,'42501');
select public.update_task(current_setting('p10.id')::uuid,pg_temp.data()||'{"assigneeId":"33333333-3333-4333-8333-333333333332","assignedUnitId":"44444444-4444-4444-8444-444444444442","checklist":[{"id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","text":"Confirm checklist","done":true}]}'||jsonb_build_object('dueOn',((statement_timestamp() at time zone 'Asia/Manila')::date-1)::text),pg_temp.v(),gen_random_uuid());
select public.transition_task(current_setting('p10.id')::uuid,'{"state":"in_progress","reason":"Starting"}',pg_temp.v(),gen_random_uuid());
select public.transition_task(current_setting('p10.id')::uuid,'{"state":"blocked","reason":"Fictional blocker"}',pg_temp.v(),gen_random_uuid());
select pg_temp.rejects($q$select public.transition_task(current_setting('p10.id')::uuid,'{"state":"done","reason":"Skip blocker","evidence":"Fictional evidence"}',pg_temp.v(),gen_random_uuid())$q$,'55000');
select public.transition_task(current_setting('p10.id')::uuid,'{"state":"in_progress","reason":"Blocker resolved"}',pg_temp.v(),gen_random_uuid());
select public.transition_task(current_setting('p10.id')::uuid,'{"state":"done","reason":"Finished checklist","evidence":"Fictional final evidence"}',pg_temp.v(),gen_random_uuid());
select pg_temp.require(public.read_task(current_setting('p10.id')::uuid)->>'state'='done');
select pg_temp.require(public.read_task(current_setting('p10.id')::uuid)->>'originalDueOn'='2027-04-10');
select pg_temp.require(public.read_task(current_setting('p10.id')::uuid)->>'overdue'='false');
select pg_temp.require((public.read_tasks('22222222-2222-4222-8222-222222222221','overdue')->>'total')::integer=0);
select pg_temp.require((public.read_tasks('22222222-2222-4222-8222-222222222221','assigned')->>'total')::integer=1);
reset role;
select pg_temp.require((select count(*)=1 from public.audit_events where request_id='10000000-0000-4000-8000-000000000001'));
select pg_temp.require(not exists(select 1 from public.audit_events where redacted_diff::text like '%Fictional reason%'));
select pg_temp.require((select count(*)=1 from public.task_revisions where work_item_id=current_setting('p10.id')::uuid and state='done' and evidence='Fictional final evidence'));
update public.role_assignments set status='active' where term_membership_id='66666666-6666-4666-8666-666666666662' and role_id='55555555-5555-4555-8555-555555555559';
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333331',true);
select set_config('p10.review',public.create_task('22222222-2222-4222-8222-222222222221',pg_temp.data()||'{"taskType":"review_required","checklist":[]}',gen_random_uuid())->>'workItemId',true);
select public.transition_task(current_setting('p10.review')::uuid,'{"state":"ready_for_review","reason":"Ready","evidence":"Original submission"}',1,gen_random_uuid());
select pg_temp.rejects($q$select public.update_task(current_setting('p10.review')::uuid,pg_temp.data()||'{"taskType":"review_required","checklist":[]}',2,gen_random_uuid())$q$,'55000');
select pg_temp.rejects($q$select public.transition_task(current_setting('p10.review')::uuid,'{"state":"done","reason":"Self review","evidence":"My proof"}',2,gen_random_uuid())$q$,'55000');
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333332',true);
select public.transition_task(current_setting('p10.review')::uuid,'{"state":"done","reason":"Independent head review","evidence":"Reviewed final rendition"}',2,gen_random_uuid());
select pg_temp.require(public.read_task(current_setting('p10.review')::uuid)->>'state'='done');
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333331',true);
select set_config('p10.governed',public.create_task('22222222-2222-4222-8222-222222222221',pg_temp.data()||'{"taskType":"governed","checklist":[]}',gen_random_uuid())->>'workItemId',true);
select pg_temp.rejects($q$select public.transition_task(current_setting('p10.governed')::uuid,'{"state":"done","reason":"Try bypass","evidence":"Not FIN approval"}',1,gen_random_uuid())$q$,'55000');
select 'ok 3 - P10_A3: assignee progress/checklist/blocked/evidence completion, metadata scope, original date and redacted attributed history' as tap;
rollback;
